:root {
  --bg: #1a1c2c;
  --card: #29366f;
  --ink: #f4f4f4;
  --accent: #ffcd75;
  --accent-2: #38b764;
  --danger: #b13e53;
  --line: #566c86;
}
* { box-sizing: border-box; }
body {
  margin: 0;
  min-height: 100vh;
  display: grid;
  place-items: center;
  padding: 16px;
  background: var(--bg);
  background-image: linear-gradient(45deg, #20233a 25%, transparent 25%, transparent 75%, #20233a 75%),
    linear-gradient(45deg, #20233a 25%, transparent 25%, transparent 75%, #20233a 75%);
  background-size: 24px 24px;
  background-position: 0 0, 12px 12px;
  color: var(--ink);
  font-family: ui-monospace, "Courier New", monospace;
  font-size: 16px;
}
.card {
  width: min(100%, 420px);
  background: var(--card);
  border: 4px solid var(--line);
  box-shadow: 8px 8px 0 #0d0f1a;
  padding: 20px;
}
h1 { margin: 0 0 4px; font-size: 24px; letter-spacing: 2px; color: var(--accent); }
.subtitle { margin: 0 0 18px; font-size: 14px; color: #9bb0c9; }
.add-row { display: flex; gap: 8px; }
input, button {
  font: inherit;
  padding: 10px 12px;
  border: 3px solid var(--line);
  background: #1a1c2c;
  color: var(--ink);
  border-radius: 0;
}
input { flex: 1; min-width: 0; }
input:focus, button:focus-visible { outline: 3px solid var(--accent); outline-offset: 2px; }
button {
  cursor: pointer;
  background: var(--accent);
  color: #1a1c2c;
  font-weight: 700;
  box-shadow: 3px 3px 0 #0d0f1a;
}
button:hover { filter: brightness(1.1); }
button:active { transform: translate(3px, 3px); box-shadow: none; }
.help { margin: 8px 0 16px; font-size: 13px; color: #9bb0c9; }
.counts { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin-bottom: 16px; }
.count-box { background: #1a1c2c; border: 3px solid var(--line); padding: 8px; text-align: center; }
.count-label { display: block; font-size: 12px; letter-spacing: 1px; color: #9bb0c9; }
.count-value { display: block; font-size: 22px; font-weight: 700; color: var(--accent); }
.todo-list { list-style: none; margin: 0; padding: 0; display: grid; gap: 10px; }
.todo-item {
  display: flex;
  align-items: center;
  gap: 10px;
  background: #1a1c2c;
  border: 3px solid var(--line);
  padding: 8px 10px;
  word-break: break-word;
}
.todo-item.done .todo-text { text-decoration: line-through; color: #9bb0c9; }
.todo-text { flex: 1; }
.todo-check { width: 22px; height: 22px; accent-color: var(--accent-2); cursor: pointer; flex-shrink: 0; }
.todo-delete {
  padding: 4px 8px;
  font-size: 14px;
  background: var(--danger);
  color: var(--ink);
  box-shadow: 2px 2px 0 #0d0f1a;
  flex-shrink: 0;
}
.empty { text-align: center; color: #9bb0c9; font-size: 14px; margin: 12px 0 0; }
.visually-hidden {
  position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px;
  overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0;
}
@media (max-width: 400px) {
  .card { padding: 14px; }
  h1 { font-size: 20px; }
}

(function () {
  "use strict";

  const form = document.getElementById("todo-form");
  const input = document.getElementById("todo-input");
  const list = document.getElementById("todo-list");
  const totalEl = document.getElementById("todo-total");
  const remainingEl = document.getElementById("remaining");
  const emptyMsg = document.getElementById("empty-msg");

  let nextId = 1;
  const tasks = [];

  function updateCounts() {
    totalEl.textContent = String(tasks.length);
    const remaining = tasks.filter((t) => !t.done).length;
    remainingEl.textContent = String(remaining);
    emptyMsg.style.display = tasks.length === 0 ? "block" : "none";
  }

  function addTask(text) {
    const trimmed = text.trim();
    if (!trimmed) return;

    const id = nextId++;
    const task = { id, text: trimmed, done: false };
    tasks.push(task);

    const li = document.createElement("li");
    li.className = "todo-item";
    li.dataset.id = String(id);

    const checkbox = document.createElement("input");
    checkbox.type = "checkbox";
    checkbox.className = "todo-check";
    checkbox.id = "todo-check-" + id;
    checkbox.setAttribute("aria-label", "Mark task " + id + " complete");

    const span = document.createElement("span");
    span.className = "todo-text";
    span.id = "todo-text-" + id;
    span.textContent = trimmed;

    const del = document.createElement("button");
    del.type = "button";
    del.className = "todo-delete";
    del.id = "todo-delete-" + id;
    del.textContent = "Del";
    del.setAttribute("aria-label", "Delete task " + id);

    checkbox.addEventListener("change", function () {
      task.done = checkbox.checked;
      li.classList.toggle("done", task.done);
      updateCounts();
    });

    del.addEventListener("click", function () {
      const index = tasks.indexOf(task);
      if (index !== -1) tasks.splice(index, 1);
      li.remove();
      updateCounts();
    });

    li.appendChild(checkbox);
    li.appendChild(span);
    li.appendChild(del);
    list.appendChild(li);

    updateCounts();
  }

  form.addEventListener("submit", function (e) {
    e.preventDefault();
    addTask(input.value);
    input.value = "";
    input.focus();
  });

  updateCounts();
})();
